window.kbPageData["views/entry/k-032e611a75e3d09a"] = {"key":"entry/k-032e611a75e3d09a","state":{"route":"entry/k-032e611a75e3d09a"},"node":{"id":"k-032e611a75e3d09a","mode":"k","title":"保护他人民事权益受损时的受益人补偿","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["因保护他人民事权益受损时的侵权责任和受益人补偿","保护他人民事权益受损时受益人的适当补偿义务"],"qs":["江苏 2024 A类 行测#8","江苏 2024 B类 行测#12"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"因保护他人民事权益而受损的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受损者请求补偿的，受益人应当给予适当补偿。","review":{"definition":"因保护他人民事权益而受损的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受损者请求补偿的，受益人应当给予适当补偿。","explanation":"王某失控翻车，李某赶去救助时自行摔伤。题干未交代有人侵害李某的权益，参考答案按无侵权人的情形选A。A项省略了李某提出补偿请求这一条件，完整结论是李某提出请求后，受益人王某应当适当补偿。李某施救时造成王某面部受伤属于另一问题，适用自愿紧急救助的免责规则。","references":[{"source":"web-bd7415d8b4007136","location":"第一百八十三条、第一百八十四条","quote":"受害人请求补偿的，受益人应当给予适当补偿"}],"evidence":"请求补偿的，受益人应当给予适当补偿。","disposition":"独立词条","basis":"据原题与所列资料编释。","title":"保护他人民事权益受损时的受益人补偿","related":[],"examFocus":{"江苏 2024 A类 行测#8":"区分救助途中施救人受伤、施救时受助人受伤和在值班期间参与救助三种情况，分别判断适用的法律规则。"}},"readings":[{"origin":"k-032e611a75e3d09a","title":"保护他人民事权益受损时的受益人补偿","qs":["江苏 2024 A类 行测#8"],"definition":"因保护他人民事权益而受损的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受损者请求补偿的，受益人应当给予适当补偿。","explanation":"王某失控翻车，李某赶去救助时自行摔伤。题干未交代有人侵害李某的权益，参考答案按无侵权人的情形选A。A项省略了李某提出补偿请求这一条件，完整结论是李某提出请求后，受益人王某应当适当补偿。李某施救时造成王某面部受伤属于另一问题，适用自愿紧急救助的免责规则。","evidence":"请求补偿的，受益人应当给予适当补偿。","doubt":"","references":[{"source":"web-bd7415d8b4007136","location":"第一百八十三条、第一百八十四条","quote":"受害人请求补偿的，受益人应当给予适当补偿"}]},{"origin":"k-349991e34929c682","title":"保护他人民事权益受损时的受益人补偿","qs":["江苏 2024 B类 行测#12"],"definition":"因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任时，受害人请求补偿的，受益人应当给予适当补偿。","explanation":"李某赶去救助翻车的王某时自行摔伤，题干未交代有侵权人。按本题情形，李某提出补偿请求后，受益人王某应给予适当补偿，因此A项成立。施救时另行造成王某面部受伤，并不使李某因救助受伤而享有的补偿请求权消失。","evidence":"受益人应当给予适当补偿","doubt":"","references":[]}]},"questions":{"江苏 2024 A类 行测#8":{"paper":"江苏 2024 A类 行测","n":8,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",3],"card":"eb776cae7db026319d933503","links":[{"id":"k-032e611a75e3d09a","role":"直接考查","why":"侵权人承担民事责任，受益人可以适当补偿。无侵权人、侵权人逃逸或无力担责时，受损人请求补偿的，受益人应当适当补偿。"}]},"江苏 2024 B类 行测#12":{"paper":"江苏 2024 B类 行测","n":12,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",2],"asrc":["8dd171daee6fc74e9718.pdf",5],"card":"24e2d5832ef43160771f7921","links":[{"id":"k-032e611a75e3d09a","role":"直接考查","why":"救助人为保护他人权益受伤且没有侵权人时，受益人应在救助人请求后给予适当补偿。"}]}},"terms":{},"references":{"web-bd7415d8b4007136":{"name":"《中华人民共和国民法典》","url":"https://www.cac.gov.cn/2020-06/01/c_1592561777268319.htm"}},"topics":[],"units":{"k-032e611a75e3d09a":[["江苏 2024 A类 行测#8","江苏 2024 B类 行测#12"]]}};
